const r = $input.first().json;
const s = r.by_status ?? {};
const n = k => s[k] ?? 0;
const order = ['interested', 'applied', 'interviewing', 'offer', 'rejected', 'ghosted', 'withdrawn'];

const sent = ['applied', 'interviewing', 'offer', 'rejected', 'ghosted', 'withdrawn'].reduce((t, k) => t + n(k), 0);
const responded = n('interviewing') + n('offer') + n('rejected');
const rate = sent ? Math.round(responded / sent * 100) : 0;

const text = [
  '📊 Job Hunter',
  '',
  'Last 7 days',
  `• Scored: ${r.scored_7d}`,
  `• Alerted: ${r.alerted_7d}`,
  '',
  'Applications',
  ...order.map(k => `• ${k}: ${n(k)}`),
  '',
  `Response rate: ${rate}% (${responded}/${sent})`,
].join('\n');

return [{ json: { text, chat_id: $('Parse Command').first().json.chat_id } }];

const STATUSES = ['interested', 'applied', 'interviewing', 'offer', 'rejected', 'withdrawn'];
const BUTTONS = { int: 'like', app: 'mark' };   // callback prefix → route
const msg = $json.message;
const cb = $json.callback_query;

// Button taps
if (cb) {
  const [action, idStr] = String(cb.data ?? '').split(':');
  const id = Number(idStr);
  const route = BUTTONS[action] ?? null;
  const valid = route && Number.isInteger(id) && id > 0;
  return { json: {
    kind: 'callback', callback_id: cb.id,
    chat_id: cb.message.chat.id, message_id: cb.message.message_id,
    ids: valid ? String(id) : '',
    word: route === 'mark' ? 'applied' : null,
    error: valid ? null : 'Unknown button', text: valid ? null : 'Unknown button',
    route: valid ? route : 'error',
  } };
}

// Typed commands
const text = (msg?.text ?? '').trim();
const [first = '', ...args] = text.split(/\s+/);
const cmd = first.startsWith('/') ? first.split('@')[0].toLowerCase() : null;
const ids = [...new Set(args.map(Number).filter(n => Number.isInteger(n) && n > 0))];
let word = args.find(a => Number.isNaN(Number(a)))?.toLowerCase() ?? null;

let error = null;
if (cmd === '/applied') {
  word = 'applied';
  if (ids.length === 0) error = 'Usage: /applied <id> [id...]\nExample: /applied 132 145';
}
if (cmd === '/unlike' && ids.length === 0) {
  error = 'Usage: /unlike <id> [id...]\nExample: /unlike 132';
}
if (cmd === '/status' && (ids.length === 0 || !STATUSES.includes(word))) {
  error = `Usage: /status <id> [id...] <status>\nStatuses: ${STATUSES.join(', ')}\nExample: /status 132 interviewing`;
}

const ROUTES = { '/applied': 'mark', '/unlike': 'unlike' };
const route = error ? 'error' : (ROUTES[cmd] ?? cmd);

return { json: {
  kind: 'command', cmd, ids: ids.join(' '), word,
  chat_id: msg?.chat?.id, error, text: error, route,
} };

const r = $input.first().json;
const { chat_id, word } = $('Parse Command').first().json;
const fmt = a => a.map(id => `#${id}`).join(', ');

const lines = [];
if (r.updated.length)   lines.push(`✅ ${fmt(r.updated)} → ${word}`);
if (r.not_found.length) lines.push(`❓ No such job: ${fmt(r.not_found)}`);

return [{ json: { chat_id, text: lines.join('\n') || 'Nothing changed.' } }];

const jobs = $input.first().json.jobs;
const { chat_id } = $('Parse Command').first().json;

const text = jobs.length === 0
  ? 'No liked jobs yet.\nMark one with: /status <id> interested'
  : ['❤️ Liked jobs', '',
     ...jobs.map(j => `#${j.job_id} ${j.title} — ${j.company ?? 'unknown'}\n${j.url}`)
    ].join('\n\n');

return [{ json: { chat_id, text } }];

const r = $input.first().json;
const { chat_id } = $('Parse Command').first().json;
const fmt = a => a.map(id => `#${id}`).join(', ');

const lines = [];
if (r.removed.length)   lines.push(`💔 Unliked: ${fmt(r.removed)}`);
if (r.unchanged.length) lines.push(`↪️ Not liked (or already applied): ${fmt(r.unchanged)}`);

return [{ json: { chat_id, text: lines.join('\n') || 'Nothing changed.' } }];

const r = $input.first().json;
const p = $('Parse Command').first().json;
const id = p.ids;

const text = r.liked.length     ? `❤️ Liked #${id}`
           : r.unliked.length   ? `💔 Unliked #${id}`
           : r.skipped.length   ? `↪️ #${id} is already further along`
           : r.not_found.length ? `❓ Job #${id} no longer exists`
           : 'Tap ❤️ on an alert';

return [{ json: { text, callback_id: p.callback_id } }];

const r = $input.first().json;
const p = $('Parse Command').first().json;
const fmt = a => a.map(id => `#${id}`).join(', ');

const lines = [];
if (r.updated.length)   lines.push(`✅ Marked applied: ${fmt(r.updated)}`);
if (r.skipped.length)   lines.push(`↪️ Already further along (unchanged): ${fmt(r.skipped)}`);
if (r.not_found.length) lines.push(`❓ No such job: ${fmt(r.not_found)}`);

return [{ json: {
  chat_id: p.chat_id, text: lines.join('\n') || 'Nothing changed.',
  kind: p.kind, callback_id: p.callback_id,
} }];
